package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;

/**
 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then), and
 * the number of the claim it corrects (null unless it is a correction), and the date it rounds on: its own, or for
 * a correction the date of the claim it corrects, and its number within its period (<period>-<n>, or X-<n> in no
 * period) when it was opened while the sheet numbered by period, in place of a number on the sheet (null otherwise),
 * and its due-by (yyyy-MM-dd), fixed when it was added from the terms in force on the sheet's today then (its person's own, their grade's, the sheet's),
 * and its status log, oldest first, and the date it was last deferred until (null when never), with whether it is
 * deferred now: OPEN (or VOID, voided while deferred) with that date after the sheet's today, and its proofs count, and the number (as it shows) of
 * the claim it was split off (null unless it was), and the user whose open editor locks it (null when none does),
 * and whether it was added while its period was soft-closed (a late entry), and the sheet's today it was last
 * reminded on (null when never), and its external reference (null for none), and its tags (lower-cased, sorted),
 * with every tag it has ever carried, and its comments, in the order written, and the number of the bulk settle
 * batch that last settled it (null when settled one at a time, or never), and its lines, in the order added, and
 * when it was added (the claim sequence's value; null when kept from before it was recorded), which decides the
 * forward-only rates it sees, and whether a steward waived its late charge (it then bears none), and how many of its
 * proofs are photos (the rest are receipts), and whether it is held (toggled while OPEN or PENDING): it still counts in
 * every total (a hold takes only a person's cut in the pools).
 */
public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String periodNumber, String dueBy, List<ClaimLogLine> log, String deferredUntil, boolean deferred, int proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref, List<String> tags,
        List<String> tagsEver, List<ClaimComment> comments, Integer batch, List<ClaimLine> lines, Long added, boolean waived, int photos, boolean held) {

    /** Whether this claim is a correction: a negative amount, naming the number (as it shows) of the settled claim it corrects. */
    public boolean correction() {
        return amount.startsWith("-");
    }

    /** How many of its proofs are of the kind (receipt or photo). */
    public int proofsOf(String kind) {
        return ProofKind.PHOTO.equals(kind) ? photos : ProofKind.RECEIPT.equals(kind) ? proofs - photos : 0;
    }

    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount + " date=" + date;
    }

    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
    public Claim withNumber(Integer number) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim, numbered within its period: its audit fields end with number=<period number>. */
    public Claim withPeriodNumber(String periodNumber) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim with another date (yyyy-MM-dd), as once re-dated. */
    public Claim withDate(String date) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim with another amount (two decimals), as its remaining amount once split. */
    public Claim withAmount(String amount) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim, settled with its due fixed (null when its grade had no rate). */
    public Claim withSettledDue(String settledDue) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim as an OPEN claim bound by no statement and with no due fixed: the figure it would have live. */
    public Claim asOpenUnbound() {
        return new Claim(id, person, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false, null, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim as it stands with the date for the sheet's today: deferred while OPEN (or VOID) with its deferred-until after it. */
    public Claim on(LocalDate today) {
        boolean deferredThen = (status == ClaimStatus.OPEN || status == ClaimStatus.VOID) && deferredUntil != null && LocalDate.parse(deferredUntil).isAfter(today);
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferredThen, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim, with its comments (in the order written). */
    public Claim withComments(List<ClaimComment> comments) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim, with its lines (in the order added). */
    public Claim withLines(List<ClaimLine> lines) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** This claim, with its status log (oldest first). */
    public Claim withLog(List<ClaimLogLine> log) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch, lines, added, waived, photos, held);
    }

    /** The date it was last settled: its status log's last SETTLED line (null when the log has none). */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log == null ? List.<ClaimLogLine>of() : log) {
            if (line.status() == ClaimStatus.SETTLED) {
                on = LocalDate.parse(line.on());
            }
        }
        return on;
    }

    /** The date it was last deleted: its status log's last DELETED line (null when the log has none). */
    public LocalDate deletedOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log == null ? List.<ClaimLogLine>of() : log) {
            if (line.status() == ClaimStatus.DELETED) {
                on = LocalDate.parse(line.on());
            }
        }
        return on;
    }

    /** The number the claim shows: its number within its period, else its number on the sheet; null for none. */
    public String shownNumber() {
        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
    }

    /** The audit fields of a status change: {@link #auditFields} then number=<number> when it has one. */
    public String statusAuditFields(String person) {
        String shown = shownNumber();
        return auditFields(person) + (shown == null ? "" : " number=" + shown);
    }

    /** Whether this claim counts toward the totals: OPEN, PENDING and SETTLED claims do, unless deferred. */
    public boolean counts() {
        return !deferred && (status == ClaimStatus.OPEN || status == ClaimStatus.PENDING || status == ClaimStatus.SETTLED);
    }

    /**
     * The status this claim had at the end of the day, as its status log records it (the last line on or before it);
     * null when it was not yet added then. A claim kept from before the log (no lines) has its status now.
     */
    public ClaimStatus statusOn(LocalDate end) {
        if (log == null || log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogLine line : log) {
            if (!LocalDate.parse(line.on()).isAfter(end)) {
                then = line.status();
            }
        }
        return then;
    }

    /** Whether this claim's statement binds its figure: it is stated (a PENDING claim too, like any that counts). */
    public boolean bound() {
        return stated;
    }

    /**
     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
     * settled or bound when its grade had no rate keeps none).
     */
    public boolean fixed() {
        return settledDue != null || (bound() && statedDue != null);
    }

    /**
     * This claim's due: the due fixed when settled; else the due its statement bound (as shown then, late charge
     * included); else its floored figure (the greater of the sheet's floor in force on its date and its {@link #figure})
     * plus, while it is overdue, its late charge on that floored figure (a correction has no floor and no charge); null
     * when there is no figure.
     */
    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
        if (figure == null || settledDue != null || bound() || correction()) {
            return figure;
        }
        BigDecimal floored = figure.max(floor.on(date));
        return floored.add(late.charge(this, grade, floored));
    }

    /**
     * This claim's figure: the due fixed when settled, else the due its statement bound (as shown, late charge
     * included), else
     * its amount at the grade's rate in force on its date, of the rates it sees (the floor is applied before the late charge, in {@link #due}); null when
     * there is none.
     */
    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
    }

    /** This claim's {@link #figure}, its live figure rounded by the mode. */
    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (bound()) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        return Rate.due(amount, Rate.on(Rate.seenBy(rates, added), grade, LocalDate.parse(date)), rounding);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;
import net.officefloor.hq.app.holiday.Holidays;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, each belonging to a person on that sheet. */
@Repository
public class Claims {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("corrects"), rs.getDate("rounds_on").toLocalDate().toString(),
            rs.getString("period_number"), rs.getDate("due_by").toLocalDate().toString(), List.of(),
            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
            rs.getString("locked_by"), rs.getBoolean("late_entry"),
            rs.getDate("reminded_on") == null ? null : rs.getDate("reminded_on").toLocalDate().toString(),
            rs.getString("ref"), tagList(rs.getString("tags")), tagList(rs.getString("tags_ever")), List.of(),
            rs.getObject("batch", Integer.class), List.of(), rs.getObject("added", Long.class),
            rs.getBoolean("waived"), rs.getInt("proof_photos"), rs.getBoolean("held"));

    /** The tags kept as comma separated text (empty for none). */
    private static List<String> tagList(String kept) {
        return kept == null || kept.isEmpty() ? List.of() : List.of(kept.split(","));
    }

    /** The tags as kept: comma separated, sorted. */
    private static String kept(List<String> tags) {
        return String.join(",", tags);
    }

    // A claim rounds on its own date; a correction on the date of the claim it corrects (its own when none has it).
    // It is deferred while OPEN (or VOID, voided while deferred) with its deferred-until after the sheet's today (the real date until one is set).
    private static final String COLUMNS = "SELECT claim.id, claim.person, claim.amount, claim.claimed_on, claim.note, claim.status,"
            + " claim.number_on_sheet, claim.settled_due, claim.opened_by, claim.stated, claim.stated_due, claim.corrects,"
            + " claim.period_number, claim.due_by, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on,"
            + " claim.deferred_until, claim.proofs, claim.split_from, claim.locked_by, claim.late_entry, claim.reminded_on, claim.ref, claim.tags, claim.tags_ever, claim.batch, claim.added, claim.waived, claim.proof_photos, claim.held, (claim.status IN ('OPEN', 'VOID') AND claim.deferred_until IS NOT NULL AND claim.deferred_until >"
            + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE)) AS deferred FROM claim"
            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";

    // The place after every claim listed on the sheet (bound to the sheet), so the claim lists newest.
    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final String LOG = "SELECT claim, status, by_user, on_date, due FROM claim_log WHERE sheet = ?";

    private static final String COMMENTS = "SELECT claim, by_user, on_date, text FROM claim_comment WHERE sheet = ?";

    private static final String LINES = "SELECT claim, label, qty, unit FROM claim_line WHERE sheet = ?";

    /** Every claim on the sheet, newest first. */
    public List<Claim> list(String sheet) {
        return withLines(withComments(withLogs(sheet, jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.listed DESC, claim.id DESC", ROW, sheet),
                jdbc.query(LOG + " ORDER BY id", LOG_ROW, sheet)), jdbc.query(COMMENTS + " ORDER BY id", COMMENT_ROW, sheet)),
                jdbc.query(LINES + " ORDER BY id", LINE_ROW, sheet));
    }

    public Claim find(String sheet, long id) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
        return found.isEmpty() ? null
                : withLines(withComments(withLogs(sheet, found, jdbc.query(LOG + " AND claim = ? ORDER BY id", LOG_ROW, sheet, id)),
                        jdbc.query(COMMENTS + " AND claim = ? ORDER BY id", COMMENT_ROW, sheet, id)),
                        jdbc.query(LINES + " AND claim = ? ORDER BY id", LINE_ROW, sheet, id)).get(0);
    }

    private record Lined(long claim, ClaimLine line) {
    }

    private static final RowMapper<Lined> LINE_ROW = (rs, i) -> new Lined(rs.getLong("claim"),
            new ClaimLine(rs.getString("label"), rs.getInt("qty"),
                    rs.getBigDecimal("unit").setScale(2, RoundingMode.UNNECESSARY).toPlainString()));

    /** The claims, each with its own lines (in the order added). */
    private static List<Claim> withLines(List<Claim> found, List<Lined> lined) {
        Map<Long, List<ClaimLine>> lines = new HashMap<>();
        for (Lined l : lined) {
            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
        }
        return found.stream().map(c -> c.withLines(lines.getOrDefault(c.id(), List.of()))).toList();
    }

    /**
     * Adds a line to a draft claim not locked by another user's editor, setting its amount to the lines' total and
     * recording the user as its last editor; conditional on the amount read, so a concurrent change is refused: false
     * when it is no longer a draft with that amount, or another user's editor holds it.
     */
    public boolean addLine(String sheet, long id, String user, BigDecimal was, BigDecimal total, String label, int qty,
            BigDecimal unit) {
        if (jdbc.update("UPDATE claim SET amount = ?, edited_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
                + " AND amount = ? AND (locked_by IS NULL OR locked_by = ?)", total, user, sheet, id, was, user) != 1) {
            return false;
        }
        jdbc.update("INSERT INTO claim_line (sheet, claim, label, qty, unit) VALUES (?, ?, ?, ?, ?)", sheet, id, label,
                qty, unit);
        return true;
    }

    private record Commented(long claim, ClaimComment comment) {
    }

    private static final RowMapper<Commented> COMMENT_ROW = (rs, i) -> new Commented(rs.getLong("claim"),
            new ClaimComment(rs.getString("by_user"), rs.getDate("on_date").toLocalDate().toString(), rs.getString("text")));

    /** The claims, each with its own comments (in the order written). */
    private static List<Claim> withComments(List<Claim> found, List<Commented> commented) {
        Map<Long, List<ClaimComment>> comments = new HashMap<>();
        for (Commented c : commented) {
            comments.computeIfAbsent(c.claim(), k -> new ArrayList<>()).add(c.comment());
        }
        return found.stream().map(c -> c.withComments(comments.getOrDefault(c.id(), List.of()))).toList();
    }

    /** Adds a comment to the claim, by the user on the date (the sheet's today). */
    public void comment(String sheet, long id, String user, LocalDate on, String text) {
        jdbc.update("INSERT INTO claim_comment (sheet, claim, by_user, on_date, text) VALUES (?, ?, ?, ?, ?)",
                sheet, id, user, Date.valueOf(on), text);
    }

    private record Logged(long claim, ClaimLogLine line) {
    }

    private static final RowMapper<Logged> LOG_ROW = (rs, i) -> new Logged(rs.getLong("claim"),
            new ClaimLogLine(ClaimStatus.valueOf(rs.getString("status")), rs.getString("by_user"),
                    rs.getDate("on_date").toLocalDate().toString(), rs.getString("due")));

    /** The claims, each with its own lines of the status log (oldest first). */
    private static List<Claim> withLogs(String sheet, List<Claim> found, List<Logged> logged) {
        Map<Long, List<ClaimLogLine>> lines = new HashMap<>();
        for (Logged l : logged) {
            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
        }
        return found.stream().map(c -> c.withLog(lines.getOrDefault(c.id(), List.of()))).toList();
    }

    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
    public Claim findByNumber(String sheet, String number) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * Adds the claim with its due-by and the terms it was fixed with; the due-by moves after only when a holiday is
     * added (see {@link #refixDueBy}); returns its id.
     */
    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy, int terms) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, ref, tags, tags_ever, due_terms, listed)"
                    + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setLong(2, person);
            ps.setBigDecimal(3, input.amount());
            ps.setDate(4, Date.valueOf(input.date()));
            ps.setString(5, input.note());
            ps.setString(6, input.corrects());
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, input.ref());
            ps.setString(9, kept(input.tags()));
            ps.setString(10, kept(input.tags()));
            ps.setInt(11, terms);
            ps.setString(12, sheet);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    private record Fixed(long id, LocalDate date, int terms) {
    }

    /**
     * Re-fixes the due-by of every claim on the sheet that is not SETTLED or VOID and whose due-by is on or after the
     * date: the terms-th business day after its date, with the terms it was fixed with, skipping weekends and the
     * holidays given.
     */
    public void refixDueBy(String sheet, LocalDate from, Set<LocalDate> holidays) {
        List<Fixed> fixed = jdbc.query("SELECT id, claimed_on, due_terms FROM claim WHERE sheet = ?"
                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ?",
                (rs, i) -> new Fixed(rs.getLong("id"), rs.getDate("claimed_on").toLocalDate(), rs.getInt("due_terms")),
                sheet, Date.valueOf(from));
        for (Fixed claim : fixed) {
            LocalDate dueBy = Holidays.businessDaysAfter(claim.date(), claim.terms(), holidays);
            jdbc.update("UPDATE claim SET due_by = ? WHERE sheet = ? AND id = ?", Date.valueOf(dueBy), sheet, claim.id());
        }
    }

    /**
     * How much the corrections made against the claim showing this number already take off it: the sum of their
     * amounts as positive values, leaving out VOID and DELETED ones and the one excluded (null for none).
     */
    public BigDecimal corrected(String sheet, String number, Long excluded) {
        BigDecimal sum = jdbc.queryForObject("SELECT COALESCE(SUM(-amount), 0) FROM claim WHERE sheet = ? AND corrects = ?"
                + " AND status NOT IN ('VOID', 'DELETED') AND id <> ?", BigDecimal.class, sheet, number, excluded == null ? -1L : excluded);
        return sum == null ? BigDecimal.ZERO : sum;
    }

    /** Whether a claim on the sheet other than the one excluded (null for none) has the reference, ignoring case. */
    public boolean refUsed(String sheet, String ref, Long excluded) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheet, ref, excluded == null ? -1L : excluded);
        return n != null && n > 0;
    }

    /** Marks the claim a late entry: added while the period its due-by falls in was soft-closed. */
    public void setLateEntry(String sheet, long id) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
    }

    /**
     * Adds the OPEN claim split off another: the amount, with the date, note and tags of the claim it was split from
     * (by the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
     */
    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, List<String> tags,
            LocalDate dueBy, int terms, String splitFrom, String openedBy) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
                    + " split_from, opened_by, tags, tags_ever, due_terms, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?, ?, "
                    + NEXT_LISTED + ")",
                    new String[] { "id" });
            ps.setString(1, sheet);
            ps.setLong(2, person);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setDate(6, Date.valueOf(dueBy));
            ps.setString(7, splitFrom);
            ps.setString(8, openedBy);
            ps.setString(9, kept(tags));
            ps.setString(10, kept(tags));
            ps.setInt(11, terms);
            ps.setString(12, sheet);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
