196	    /** This claim's {@link #figure}, its live figure rounded by the mode. */
197	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
198	        if (settledDue != null) {
199	            return new BigDecimal(settledDue);
200	        }
201	        if (bound()) {
202	            return statedDue == null ? null : new BigDecimal(statedDue);
203	        }
204	        return Rate.due(amount, Rate.on(Rate.seenBy(rates, added), grade, LocalDate.parse(date)), rounding);
205	    }
