659	     * after the last number given on any of them (1 when none has given one), recorded as the sheet's last number.
660	     * The counter rows of the whole tree stay locked until the transaction ends, so two claims opened at once
661	     * anywhere in the tree get different numbers.
662	     */
663	    public int nextNumber(String sheet, List<String> tree) {
664	        try {
665	            jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 0)", sheet);
666	        } catch (DuplicateKeyException exists) {
667	            // The sheet has given a number already: its counter is in place.
668	        }
669	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
670	        sheets.add(sheet);
