672	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_number WHERE sheet IN (" + in
673	                + ") ORDER BY sheet FOR UPDATE", Integer.class, sheets.toArray());
674	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
