715	/**
716	 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
717	 * by the due-by fixed when it was added. The charge follows the sheet's today, except on a claim bound by a statement, whose due (charge included) is
718	 * the one the statement bound.
719	 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
720	 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
721	 * that date is given past its due-by before it is overdue. And the sheet's rounding mode as recorded by from-date,
722	 * which, where one is in force on the date a claim rounds on, decides its rounding in place of the policy date.
723	 */
724	public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace,
725	        List<DatedValue> roundingModes) {
726	
727	    /**
728	     * How the claim's live figures round: by the rounding mode in force on the date it rounds on (its own, or for a
729	     * correction the date of the claim it corrects) where there is one; else half up when that date is before the
730	     * policy date, half to even on or after it.
731	     */
732	    public RoundingMode rounding(Claim claim) {
733	        LocalDate on = LocalDate.parse(claim.roundsOn());
734	        String mode = roundingModes == null ? "" : Settings.on(roundingModes, on);
735	        if ("half-up".equals(mode)) {
736	            return RoundingMode.HALF_UP;
737	        }
738	        if ("half-even".equals(mode)) {
739	            return RoundingMode.HALF_EVEN;
740	        }
741	        return on.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
742	    }
743	
744	    /**
745	     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
746	     * grade (its person's in force on its date; null for none) in force on its date, if any.
747	     */
748	    public LocalDate graceBy(Claim claim, String grade) {
749	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
750	        List<DatedValue> history = grade == null ? null : grace.get(grade);
751	        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
752	        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
753	    }
754	
755	    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
756	    public boolean overdue(Claim claim, String grade) {
757	        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
758	    }
759	
760	    /**
761	     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
762	     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
763	     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
764	     * nothing); 0.00 when it is not overdue, and always for a correction or a claim whose charge was waived.
765	     */
766	    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
767	        BigDecimal total = BigDecimal.ZERO.setScale(2);
768	        if (figure == null || claim.correction() || claim.waived() || !overdue(claim, grade)) {
769	            return total;
770	        }
771	        LocalDate dueBy = graceBy(claim, grade);
772	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
773	        for (long k = 1; k <= periods; k++) {
774	            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
775	            if (boundaryPct.signum() != 0) {
776	                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
777	            }
778	        }
779	        return total;
780	    }
781	}
