817	        this.claims = claims;
818	        this.people = people;
819	        this.rates = rates;
820	        this.settings = settings;
821	        this.clock = clock;
822	        this.transaction = new TransactionTemplate(transactions);
823	        this.transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
824	    }
825	
826	    public Then on(String sheet, long id, LocalDate date) {
827	        return transaction.execute((status) -> {
828	            status.setRollbackOnly();
829	            state.show(sheet, date);
830	            Claim claim = claims.find(sheet, id);
831	            Person person = claim == null ? null : people.find(sheet, claim.person());
832	            if (person == null) {
833	                return new Then(false, null);
834	            }
835	            return new Then(true, claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
836	                    settings.late(sheet, clock.today(sheet))));
837	        });
838	    }
839	}
840	package net.officefloor.hq.app.claim;
841	
842	/**
843	 * Where a claim is in its life: only OPEN, PENDING and SETTLED claims count toward the totals. A clerk's settle of a
844	 * due above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A steward
845	 * may void a SETTLED claim within 7 days of its settlement. A DRAFT may be DELETED (counting nowhere, not editable,
846	 * openable nor voidable), and restored to a DRAFT on the sheet-today it was deleted. A DRAFT whose due is above the
847	 * review threshold in force on its date goes to REVIEW when opened (counting nowhere, not editable, settleable nor
848	 * splittable, but voidable), which a steward's review makes OPEN.
849	 */
850	public enum ClaimStatus {
851	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
852	
853	    /** The status a change takes this claim to, or null when the change is not allowed from here. */
854	    public ClaimStatus after(ClaimStatusChange change) {
855	        return switch (change) {
856	            case OPEN -> this == DRAFT ? OPEN : null;
857	            case HOLD_FOR_REVIEW -> this == DRAFT ? REVIEW : null;
858	            case REVIEW -> this == REVIEW ? OPEN : null;
859	            case SETTLE -> this == OPEN ? SETTLED : null;
860	            case PEND -> this == OPEN ? PENDING : null;
861	            case APPROVE -> this == PENDING ? SETTLED : null;
862	            case REJECT -> this == PENDING ? OPEN : null;
863	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW ? VOID : null;
864	            case DELETE -> this == DRAFT ? DELETED : null;
865	            case RESTORE -> this == DELETED ? DRAFT : null;
866	        };
867	    }
868	}
