/**
 * A viewer sees every screen and changes nothing: every write to a sheet (POST or PUT) by a user the sheet makes
 * a viewer is refused with a 400 before any step runs, so nothing is written nor audited. The bulk actions are let
 * through: they refuse each selected item themselves (the claim status rules refuse a viewer), reporting 0 done; so is
 * a viewer's bulk grade and bulk retire, which change no one, and a viewer's generate of planned claims, which makes none.
 * An archived sheet refuses every write the same way, whoever makes it. So does a screen showing the sheet as of a
 * date (?asOf=), bulk actions included: nothing changes while the as-of date is set.
 * A user's own locale and people-list columns are not a change to the sheet: anyone may choose theirs, whatever the sheet.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ViewerGuard extends OncePerRequestFilter {

    private static final Pattern SHEET_WRITE = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    /** The writes that report per-item counts, so a viewer's press goes through with every item refused. */
    private static final Set<String> BULK = Set.of("/claims/bulk-open", "/claims/bulk-settle", "/claims/bulk-void");

    /** The writes that report a count, so a viewer's press goes through and changes no one (still refused when archived). */
    private static final Set<String> VIEWER_COUNTED = Set.of("/people/bulk-grade", "/people/bulk-retire",
            "/plans/generate");

    /** The user's own locale: how the screen shows the sheet to them, never a change to it. */
    private static final String LOCALE = "/locale";

    /** The user's own people-list columns: which cells their screen shows, never a change to the sheet. */
    private static final String COLUMNS = "/columns";

    private final Roles roles;
    private final SheetArchive archive;

    public ViewerGuard(Roles roles, SheetArchive archive) {
        this.roles = roles;
        this.archive = archive;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String user = request.getParameter("user");
        Matcher own = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        if (own.matches() && (LOCALE.equals(own.group(2)) || COLUMNS.equals(own.group(2)))) {
            chain.doFilter(request, response);
            return;
        }
        if (("POST".equals(method) || "PUT".equals(method)) && request.getParameter(AsOfView.PARAM) != null
                && SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length())).matches()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Nothing changes while the sheet is shown as of a date");
            return;
        }
        if (("POST".equals(method) || "PUT".equals(method)) && user != null) {
            Matcher m = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
            if (m.matches() && !BULK.contains(m.group(2) == null ? "" : m.group(2))) {
                String sheet = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8);
                if (!VIEWER_COUNTED.contains(m.group(2) == null ? "" : m.group(2)) && Role.VIEWER.equals(roles.of(sheet, user))) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "A viewer cannot change the sheet");
                    return;
                }
                if (archive.archived(sheet)) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "An archived sheet cannot change");
                    return;
                }
            }
        }
        chain.doFilter(request, response);
    }
}
public class ResettleClaim {
    public void resettle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches) throws InvalidClaimStatusChangeException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward re-settles a claim");
        }
        if (claim.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be re-settled");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be re-settled");
        }
        Person person = people.find(sheet, claim.person());
        BigDecimal was = claim.settledDue() == null ? null : new BigDecimal(claim.settledDue());
        BigDecimal due = claim.asOpenUnbound().due(rates.list(sheet), person.gradeOn(claim.date()),
                settings.floor(sheet), settings.late(sheet, clock.today(sheet)));
        Rollup.Snapshot before = rollup.take(sheet);
        if (!claims.resettle(sheet, claim.id(), was, due)) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        log.record(sheet, user, claim.id());
        audit.record("CLAIM_RESETTLED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name())
                + " old=" + (was == null ? "n/a" : was.toPlainString())
                + " new=" + (due == null ? "n/a" : due.toPlainString()));
        watches.notify(sheet, user, person.id(), person.name(), claim.shownNumber());
        rollup.record(sheet, user, before);
    }
}
/**
 * Part-settles an OPEN claim: splits the amount off it as the Split button does, then settles the new claim as the
 * Settle button does (to PENDING when the clerk limit says so). The four-eyes rules and the proof rule are judged on
 * the claim part-settled, not the new one (whose opener is the user). Any refusal refuses the whole action: its
 * savepoint rolls back and the audit records held meanwhile are dropped.
 */
public class SettlePartClaim {
    public void settle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val BigDecimal amount,
            @Val Claim claim, ClaimSplitter splitter, ClaimStatusChanger changer, Claims claims, Audit audit,
            PlatformTransactionManager transactions) throws InvalidClaimStatusChangeException {
        TransactionTemplate transaction = new TransactionTemplate(transactions);
        transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
        audit.hold();
        try {
            transaction.execute((status) -> {
                try {
                    // Judged on the claim part-settled first, so its opener and editor may not settle part of it.
                    changer.vet(sheet, user, claim, ClaimStatusChange.SETTLE, null);
                    Claim part = splitter.split(sheet, user, claim, amount);
                    changer.settlePart(sheet, user, part);
                } catch (InvalidClaimStatusChangeException refused) {
                    throw new Refused(refused);
                }
                return null;
            });
        } catch (Refused refused) {
            audit.discard();
            throw refused.cause;
        } catch (RuntimeException failed) {
            audit.discard();
            throw failed;
        }
        audit.release();
    }

    private static final class Refused extends RuntimeException {
        private final InvalidClaimStatusChangeException cause;

        private Refused(InvalidClaimStatusChangeException cause) {
            super(cause);
            this.cause = cause;
        }
    }
}
