            } catch (InvalidClaimStatusChangeException e) {
                refusal = true;
            }
        }
        if (refusal) {
            response.send(new BulkSettleResponse(0, refused + selected.size(), claims.list(sheet), batches.last(sheet)));
            return;
        }
