/** Adds a hold to the person: their OPEN claims dated within it, unless bound by a statement, count in no live total. */
public class HoldPerson {
    public void hold(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val Hold hold, People people, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        people.hold(person.id(), hold);
        audit.record("PERSON_HELD sheet=" + sheet + " by=" + user + " name=" + person.name() + " from=" + hold.from());
        rollup.record(sheet, user, before);
    }
}
=== person/AddImportedPeople.java
/**
 * Takes each checked line, in order: a line matching a person on the sheet updates them as the person form's
 * SavePerson does (grade from the sheet's today; terms and contact only when the line gives them), any other adds a
 * person as the form's BuildPerson does.
 */
public class AddImportedPeople {
    public void add(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val ImportedPeople imported, People people, SheetClock clock, Audit audit, Rollup rollup,
            ObjectResponse<ImportResponse> response)
            throws DuplicatePersonNameException, StalePersonException, InvalidPersonException {
        int added = 0;
        int updated = 0;
        for (ImportedPeople.Line line : imported.lines()) {
            PersonRequest request = line.request();
            if (line.existing() != null) {
                // Re-read so each is saved as the store holds it after the lines before it.
                Person current = people.find(sheet, line.existing().id());
                SavePerson.apply(sheet, user, current,
                        new PersonRequest(current.name(), request.grade(), null, null,
                                request.termsDays() != null ? request.terms()
                                        : current.terms() == null ? "" : current.terms().toString(),
                                request.contactOrNull() != null ? request.contact()
                                        : current.contact() == null ? "" : current.contact(), null),
                        people, clock, audit, rollup);
                updated++;
                continue;
            }
            Rollup.Snapshot before = rollup.take(sheet);
            Person person = people.add(sheet, request.name(), request.grade(), request.termsDays(), request.contactOrNull());
            audit.record("PERSON_ADDED sheet=" + sheet + " by=" + user + " name=" + person.name() + " grade="
                    + person.grade() + (person.terms() == null ? "" : " terms=" + person.terms())
                    + (person.contact() == null ? "" : " contact=" + person.contact()));
            rollup.record(sheet, user, before);
            added++;
        }
        response.send(new ImportResponse(added, updated, people.list(sheet)));
    }
}
=== sheet/SaveToday.java
public class SaveToday {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val LocalDate today,
            SheetClock clock, PeriodCloser closer, Rollup rollup, Claims claims, SheetStates states, SheetSnapshots snapshots,
            SnapshotLines lines, Audit audit) {
        Rollup.Snapshot before = rollup.take(sheet);
        // A change of today releases every claim editor's lock on the sheet.
        LocalDate was = clock.today(sheet);
        if (!today.equals(was)) {
            claims.unlockAll(sheet);
            // What the sheet holds at the end of its old today is kept, for a statement taken as of that date.
            states.keep(sheet, was, today);
            // Every row it holds is kept too, for the screen shown as of that date: before the snapshot lines of
            // leaving it, which were not there yet on that date.
            snapshots.keep(sheet, was, today);
            // Each person's due-total as it stood on the day being left, in list order.
            for (Map.Entry<Long, Rollup.Figures> entry : before.people().entrySet()) {
                Rollup.Figures figures = entry.getValue();
                lines.add(sheet, entry.getKey(), was, figures.dueTotal());
                audit.record("SNAPSHOT sheet=" + sheet + " by=" + user + " name=" + figures.name() + " due-total="
                        + figures.dueTotal());
            }
        }
        clock.setToday(sheet, today);
        // Periods past their grace days close before the figures the today change moved are audited.
        closer.autoClose(sheet, user);
        rollup.record(sheet, user, before);
    }
}
